using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using TMPro;
namespace LWS.TruckBilliards.Editor {
public static class BilliardsBallVisualAuthoring {
 const string Root="Assets/TruckBilliards/Materials/RollingBalls";
 static readonly Color[] Colors={new Color(.96f,.965f,.95f),new Color(1,.76f,.025f),new Color(.025f,.15f,.8f),new Color(.8f,.035f,.055f),new Color(.36f,.055f,.56f),new Color(1,.28f,.035f),new Color(.035f,.34f,.12f),new Color(.38f,.025f,.04f),new Color(.015f,.018f,.024f)};
 static Texture2D ReadAtlas(Texture2D source){var rt=RenderTexture.GetTemporary(source.width,source.height,0,RenderTextureFormat.ARGB32);var old=RenderTexture.active;Graphics.Blit(source,rt);RenderTexture.active=rt;var copy=new Texture2D(source.width,source.height,TextureFormat.RGBA32,false);copy.ReadPixels(new Rect(0,0,source.width,source.height),0,0);copy.Apply();RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);return copy;}
 static Texture2D Save(Texture2D texture,string name,bool alpha=false){string path=Root+"/"+name+".png";File.WriteAllBytes(path,texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Default;importer.mipmapEnabled=true;importer.sRGBTexture=true;importer.alphaIsTransparency=alpha;importer.wrapMode=alpha?TextureWrapMode.Clamp:TextureWrapMode.Repeat;importer.filterMode=FilterMode.Trilinear;importer.maxTextureSize=1024;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static float Ink(TMP_FontAsset font,Texture2D atlas,string digits,float x,float y){if(Mathf.Abs(y)>.72f)return 0;float glyphWidth=digits.Length==1?.95f:.70f,total=glyphWidth*digits.Length;float dx=x+total*.5f;if(dx<0||dx>=total)return 0;int index=Mathf.Min(digits.Length-1,(int)(dx/glyphWidth));float u=(dx-index*glyphWidth)/glyphWidth,v=(y+.72f)/1.44f;if(u<.08f||u>.92f)return 0;var glyph=font.characterLookupTable[digits[index]].glyph.glyphRect;float value=atlas.GetPixelBilinear((glyph.x+u*glyph.width)/atlas.width,(glyph.y+v*glyph.height)/atlas.height).a;return Mathf.SmoothStep(0,1,Mathf.InverseLerp(.46f,.54f,value));}
 static Texture2D BallTexture(int number,TMP_FontAsset font,Texture2D atlas){const int width=1024,height=512;var texture=new Texture2D(width,height,TextureFormat.RGB24,true);var pixels=new Color[width*height];var tint=Colors[number<9?number:number-8];string digits=number.ToString();for(int y=0;y<height;y++){float latitude=((y+.5f)/height-.5f)*Mathf.PI;float sy=Mathf.Sin(latitude),cy=Mathf.Cos(latitude);for(int x=0;x<width;x++){float longitude=(x+.5f)/width*Mathf.PI*2;float nx=cy*Mathf.Cos(longitude),nz=cy*Mathf.Sin(longitude);Color color=number>8&&Mathf.Abs(sy)>.40f?Colors[0]:tint;if(number>0&&Mathf.Abs(nx)>.925f){color=Colors[0];float ink=Ink(font,atlas,digits,nz*(nx>0?1:-1)/.32f,sy/.32f);color=Color.Lerp(color,new Color(.014f,.016f,.02f),ink);}pixels[y*width+x]=color;}}texture.SetPixels(pixels);texture.Apply();return Save(texture,"Ball "+number);}
 static Material Material(string name,Texture2D texture,bool shadow=false){string path=Root+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find(shadow?"Universal Render Pipeline/Unlit":"Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.SetTexture("_BaseMap",texture);mat.SetColor("_BaseColor",Color.white);if(shadow){mat.SetFloat("_Surface",1);mat.SetFloat("_SrcBlend",5);mat.SetFloat("_DstBlend",10);mat.SetFloat("_ZWrite",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.renderQueue=3000;}else{mat.SetFloat("_Smoothness",.86f);mat.SetFloat("_Metallic",.035f);}EditorUtility.SetDirty(mat);return mat;}
 public static void Upgrade(BilliardsMatch match){Directory.CreateDirectory(Root);AssetDatabase.Refresh();var font=TMP_Settings.defaultFontAsset;if(font==null)throw new Exception("Default TMP font missing for curved ball numbers");font.ReadFontAssetDefinition();var atlas=ReadAtlas(font.atlasTextures[0]);var shade=new Texture2D(128,128,TextureFormat.RGBA32,true);for(int y=0;y<128;y++)for(int x=0;x<128;x++){float distance=new Vector2((x-63.5f)/64,(y-63.5f)/64).magnitude;shade.SetPixel(x,y,new Color(.015f,.025f,.018f,.34f*Mathf.Pow(Mathf.Clamp01(1-distance),1.5f)));}shade.Apply();var shadowMat=Material("Soft contact shadow",Save(shade,"Soft contact shadow",true),true);
  foreach(var ball in match.balls){var old=ball.transform.Find("Rolling sphere");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);var oldShadow=ball.transform.Find("Contact shadow");if(oldShadow!=null)UnityEngine.Object.DestroyImmediate(oldShadow.gameObject);foreach(var text in ball.GetComponentsInChildren<TextMesh>())UnityEngine.Object.DestroyImmediate(text.gameObject);var patch=ball.transform.Find("Number patch");if(patch!=null)UnityEngine.Object.DestroyImmediate(patch.gameObject);ball.GetComponent<MeshRenderer>().enabled=false;
   var visual=GameObject.CreatePrimitive(PrimitiveType.Sphere);visual.name="Rolling sphere";visual.layer=2;UnityEngine.Object.DestroyImmediate(visual.GetComponent<Collider>());visual.transform.SetParent(ball.transform,false);var renderer=visual.GetComponent<MeshRenderer>();renderer.sharedMaterial=Material("Ball "+ball.number,BallTexture(ball.number,font,atlas));renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;renderer.receiveShadows=true;
   var shadow=GameObject.CreatePrimitive(PrimitiveType.Quad);shadow.name="Contact shadow";shadow.layer=2;UnityEngine.Object.DestroyImmediate(shadow.GetComponent<Collider>());shadow.transform.SetParent(ball.transform,false);shadow.transform.rotation=Quaternion.Euler(90,0,0);shadow.transform.localScale=new Vector3(1.35f,1.35f,1);shadow.GetComponent<MeshRenderer>().sharedMaterial=shadowMat;shadow.GetComponent<MeshRenderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var display=ball.GetComponent<BilliardsBallPresentation>();if(display==null)display=ball.gameObject.AddComponent<BilliardsBallPresentation>();ball.presentation=display;display.ball=ball;display.visual=visual.transform;display.shadow=shadow.transform;display.radius=ball.sphere.radius*ball.transform.lossyScale.x;display.rackRotation=Quaternion.LookRotation(match.tableCamera.transform.right,match.tableCamera.transform.up);visual.transform.localRotation=display.rackRotation;shadow.transform.position=new Vector3(ball.initial.x,.018f,ball.initial.z);
  }UnityEngine.Object.DestroyImmediate(atlas);foreach(var light in UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include))if(light.type==LightType.Directional)light.shadows=LightShadows.Soft;AssetDatabase.SaveAssets();Debug.Log("TB_CURVED_ROLLING_SPHERES_AUTHORED physics unchanged");}
}
}